action_details.action_postfix:
// Physical nexus established - filing required
true result.id_has_nexus xdef
"Idaho filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus or doing business established - filing required
true result.id_has_nexus xdef
"Idaho filing required: Economic nexus or doing business in Idaho" job.audit_trail swap addto

// Calculate Idaho state additions
0.0 /id_additions xdef

// Common Idaho additions:
// - State income taxes deducted on federal return
// - Certain expenses related to exempt income

result.id_state_taxes_deducted 0.0 ne
{
  id_additions result.id_state_taxes_deducted add /id_additions xdef
} if

id_additions result.id_state_additions xdef

// Calculate Idaho state subtractions
0.0 /id_subtractions xdef

// Common Idaho subtractions:
// - U.S. government interest (U.S. Treasury bonds, notes, bills)
// - Idaho municipal bond interest
// - State NOL deduction (if different from federal)

result.id_us_interest_income 0.0 ne
{
  id_subtractions result.id_us_interest_income add /id_subtractions xdef
} if

result.id_municipal_interest 0.0 ne
{
  id_subtractions result.id_municipal_interest add /id_subtractions xdef
} if

id_subtractions result.id_state_subtractions xdef

"Idaho additions: $" result.id_state_additions cvs strconcat ", subtractions: $" strconcat result.id_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Idaho taxable income // Federal taxable income apportioned to ID + additions - subtractions result.id_apportioned_income result.id_state_additions add result.id_state_subtractions sub 0.0 max result.id_taxable_income xdef
// Calculate Idaho tax using flat rate: 5.3% result.id_taxable_income result.id_corp_tax_rate mul /id_tax_before_credits xdef
// Subtract Idaho state credits id_tax_before_credits result.id_state_credits sub 0.0 max result.id_tax_liability xdef
// Calculate refund or amount owed result.id_estimated_payments result.id_tax_liability sub result.id_refund_or_owed xdef
"Idaho taxable income: $" result.id_taxable_income cvs strconcat job.audit_trail swap addto "Idaho tax liability (5.3%): $" result.id_tax_liability cvs strconcat job.audit_trail swap addto
